import{_ as s,l as i,o as e,c as l,v as r,p as P,x as t,d as n,i as p,S as R}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"REST 与 gRPC","description":"","frontmatter":{"title":"REST 与 gRPC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rest-grpc.md","filePath":"cs/rest-grpc.md","lastUpdated":1789023840000}'),T={name:"cs/rest-grpc.md"};function d(c,a,C,h,E,g){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="rest-与-grpc" tabindex="-1">REST 与 gRPC <a class="header-anchor" href="#rest-与-grpc" aria-label="Permalink to &quot;REST 与 gRPC&quot;">​</a></h1><div class="epigraph"><p>REST 用资源 URI 与 HTTP 方法约束接口；gRPC 用 HTTP/2 流跑 Protobuf RPC。都是应用合同，不是新的运输层。</p><footer>—— 据 Fielding 博士论文 REST；gRPC 超 HTTP/2 实践；RFC 9110 整理</footer></div><p><a href="/cs/http-semantics">HTTP 语义</a> 给方法。<a href="/cs/sse-server-push">上一课</a> 是一种推。缺口是<strong>两种常见 API 风格</strong>：REST 资源 vs gRPC 过程调用。本课不把 Protobuf 编码写完，下一课写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>浏览器与公开 API 适合 REST：GET 可缓存、幂等合同清晰。微服务内部适合 gRPC：存根、流式 RPC、强类型。gRPC 默认 H2，浏览器要 grpc-web。REST 不是「用了 JSON 就 REST」：要统一接口与超媒体约束，课上钉常见子集。错误：REST 用状态码，gRPC 用 status 与 trailer。</p><p>不要把 gRPC 写成 QUIC 专属；H3 上的 gRPC 在演进。</p><p><span class="marginnote">Fielding 2000。gRPC 文档。本课对照，不教框架安装。</span></p><h3 id="合同不是运输" tabindex="-1">合同不是运输 <a class="header-anchor" href="#合同不是运输" aria-label="Permalink to &quot;合同不是运输&quot;">​</a></h3><p>REST 面向资源与缓存；gRPC 面向 RPC 与流。浏览器与公开 API 偏好前者。LB 要不要终止 H2 因此分叉。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：资源/方法 vs 服务/方法；缓存；浏览器；流。画：客户端 → HTTP → 资源；客户端 → H2 流 → RPC。与 WS：全双工消息 vs RPC 流。</p>',11)),(e(),P(R,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REST%5B%22%E8%B5%84%E6%BA%90%20%2B%20HTTP%20%E6%96%B9%E6%B3%95%22%5D%20--%3E%20CACHE%5B%22%E5%8F%AF%E7%BC%93%E5%AD%98%20GET%22%5D%0A%20%20GRPC%5B%22Protobuf%20RPC%22%5D%20--%3E%20H2%5B%22HTTP%2F2%20%E6%B5%81%22%5D%0A%20%20GRPC%20--%3E%20TYP%5B%22%E5%BC%BA%E7%B1%BB%E5%9E%8B%E5%AD%98%E6%A0%B9%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>负载均衡：REST 可 L7 看路径；gRPC 看服务与方法，要 H2 感知 LB。Cookie 少用于 gRPC，多用 token 头。超时与重试：REST 靠幂等头，gRPC 有 deadline，后课幂等会收。内容协商在 REST 常见，gRPC 固定编码。</p><p>与端到端：两种都要应用层校验，HTTP 成功不等于业务成功。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 GraphQL 的全部。序列化 JSON/Protobuf 是下一课。后课默认：REST 面向资源与缓存；gRPC 面向 RPC 与流。</p><p>公开互联网 API 强推 gRPC 会挡浏览器与缓存。</p><p>上一课留下的缺口在本课收口；「REST 与 gRPC」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/serialization-protobuf">序列化：JSON / Protobuf</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>REST：资源、方法、缓存合同。</li><li>gRPC：H2 上的 RPC 与流。</li><li>LB、浏览器、缓存需求不同。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Fielding REST；gRPC over HTTP/2。</li></ul>',10))])}const _=s(T,[["render",d]]);export{u as __pageData,_ as default};
